// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));

        bool ok;
        vm.prank(caller);
        try c.setOwner(caller) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
